use super::Recipient;
use super::drain;
use super::funded;
use super::super::FemMaterial;
use super::super::NATIVE_MATERIAL_DIMENSION;
use super::super::NATIVE_MATERIAL_COUNT;
use crate::patch::NativeMaterialPatch;
use crate::patch::NativeMaterialPatchCursor;
use semio_framework_value::{DslValue,NativeDecodeControl,RetirementDemand,ToValue,native_decoding::owned::NativeReceivingOriginal,retained_clone::{RetainedCloneSource,RetainedCloneGrant},retirement::RetireOwned};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[derive(semio_framework_value::RetireOwned)]
struct Patch{name:Option<String>,numbers:[Option<f64>;NATIVE_MATERIAL_COUNT]}
impl NativeMaterialPatch<NATIVE_MATERIAL_COUNT> for Patch{fn name(&self)->Option<&String>{self.name.as_ref()}fn numbers(&self)->[Option<f64>;NATIVE_MATERIAL_COUNT]{self.numbers}}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),funded(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()})).unwrap_or_else(|_|panic!("native Material patch original source")).0}
fn row()->FemMaterial{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();let row=&f["accepted"].as_array().unwrap().iter().find(|c|c["dimension"].as_u64()==Some(NATIVE_MATERIAL_DIMENSION as u64)).unwrap()["row"];type Owner=NativeReceivingOriginal<DslValue,FemMaterial>;let mut original=Some(source(DslValue::from(row)));let(mut owner,_)=Owner::begin_shell(funded(Owner::shell_demand())).unwrap();owner.admit_original(&mut original,funded(owner.original_capture_demand().unwrap())).unwrap();owner.begin_receiver(funded(owner.receiver_birth_demand().unwrap())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut recipient=Recipient;while !owner.output_ready(){let g=funded(owner.demands(4096).unwrap());assert!(control.with_construction_recipient(&mut recipient,|control|owner.advance(control,4096,g)).unwrap().progress().fits(g));}let g=funded(owner.take_demand().unwrap());let(row,_)=owner.take(g).unwrap().unwrap();drain(owner);row}
fn denied(d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{let g=funded(d);[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
#[test]
fn native_material_sparse_patch_preserves_original_field_authorities_and_all_cancelled_frontiers(){
 type Cursor=NativeMaterialPatchCursor<Patch,FemMaterial,NATIVE_MATERIAL_COUNT>;let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for case in f["cases"].as_array().unwrap(){let mut normal=0;for cut in 0..192{
  let original=source(row());let patch=source(Patch{name:case["name"].as_str().map(str::to_owned),numbers:std::array::from_fn(|i|if i==0{case["e"].as_f64()}else{None})});let foreign=source(Patch{name:case["name"].as_str().map(str::to_owned),numbers:std::array::from_fn(|i|if i==0{case["e"].as_f64()}else{None})});let d=Cursor::birth_demand();for g in denied(d){let(result,h)=observe(||Cursor::begin(g));assert!(result.is_err());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(mut cursor,_)=Cursor::begin(funded(d)).unwrap();let id=std::ptr::from_ref(original.borrow().get().id.get());let name=std::ptr::from_ref(original.borrow().get().name.get());let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut recipient=Recipient;let mut turns=0;
  while !cursor.ready()&&turns<cut{let d=cursor.demand(original.borrow(),patch.borrow(),4096).unwrap();if turns>1{assert!(cursor.demand(original.borrow(),foreign.borrow(),4096).is_err());}for g in denied(d){let(s,h)=observe(||control.with_construction_recipient(&mut recipient,|control|cursor.advance(original.borrow(),patch.borrow(),control,4096,g)).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(cursor.demand(original.borrow(),patch.borrow(),4096).unwrap(),d);}let g=funded(d);let(s,h)=observe(||control.with_construction_recipient(&mut recipient,|control|cursor.advance(original.borrow(),patch.borrow(),control,4096,g)).unwrap());assert!(s.progress().fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;}
  if cursor.ready(){normal=turns;let d=cursor.take_demand().unwrap();for g in denied(d){assert!(cursor.take(g).unwrap().is_none());}let(output,p)=cursor.take(funded(d)).unwrap().unwrap();assert!(p.fits(funded(d)));assert_eq!(std::ptr::from_ref(output.get().id.get()),id);if case["name"].is_null(){assert_eq!(std::ptr::from_ref(output.get().name.get()),name);}else{assert_ne!(std::ptr::from_ref(output.get().name.get()),name);assert_eq!(output.get().name.as_str(),case["name"].as_str().unwrap());}assert_eq!(output.get().e,case["e"].as_f64().unwrap_or(original.borrow().get().e));assert_eq!(output.get().nu,original.borrow().get().nu);assert_eq!(output.get().rho,original.borrow().get().rho);drain(output);}
  cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break;}let d=cursor.close_demand(4096).unwrap();for g in denied(d){let(s,h)=observe(||cursor.close_step(g).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let g=funded(d);let(s,h)=observe(||cursor.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(cursor.terminal_is_empty());let(_,h)=observe(||drop(cursor));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));drain(foreign);drain(patch);drain(original);if normal>0&&cut>normal{break;}
 }assert!(normal>0);eprintln!("[DEBUG] actual Material sparse patch dimension={NATIVE_MATERIAL_DIMENSION} authoredName={} everyPrefix={normal} originalId=true absentName=true deniedAxes=5 terminalHeap=0",case["name"].is_string());}
}
